<template>   <div class="cost-trend-page">     <!-- 椤靛ご -->     <ContentWrap class="page-header-card">       <div class="page-header">         <div class="page-header__main">           <div class="page-header__title">浜у搧鎴愭湰瓒嬪娍鍒嗘瀽</div>         </div>         <div class="page-header__actions">           <el-button :loading="loading" @click="loadData">             <Icon icon="ep:refresh" class="mr-5px" /> 鍒锋柊           </el-button>         </div>       </div>     </ContentWrap>      <!-- 绛涢€夊尯 -->     <ContentWrap class="filter-card">       <el-form :model="queryParams" label-width="88px" class="filter-form" @submit.prevent>         <div class="filter-grid">           <el-form-item label="浜у搧">             <el-select               v-model="queryParams.productId"               filterable               clearable               placeholder="璇烽€夋嫨浜у搧"               class="!w-full"               @change="handleQuery"             >               <el-option                 v-for="item in productList"                 :key="item.id"                 :label="item.name"                 :value="item.id"               />             </el-select>           </el-form-item>           <el-form-item label="鏃堕棿鑼冨洿">             <el-date-picker               v-model="dateRange"               type="monthrange"               value-format="YYYY-MM"               start-placeholder="寮€濮嬫湀浠?               end-placeholder="缁撴潫鏈堜唤"               class="!w-full"               @change="handleQuery"             />           </el-form-item>           <el-form-item label="瀵规瘮浜у搧">             <el-select               v-model="queryParams.compareProductIds"               multiple               filterable               clearable               placeholder="閫夋嫨瀵规瘮浜у搧锛堝彲澶氶€夛級"               class="!w-full"               @change="handleQuery"             >               <el-option                 v-for="item in productList"                 :key="item.id"                 :label="item.name"                 :value="item.id"               />             </el-select>           </el-form-item>         </div>         <div class="filter-actions">           <el-button type="primary" :loading="loading" @click="handleQuery">             <Icon icon="ep:search" class="mr-5px" /> 鏌ヨ           </el-button>           <el-button @click="resetQuery">             <Icon icon="ep:refresh-left" class="mr-5px" /> 閲嶇疆           </el-button>         </div>       </el-form>     </ContentWrap>      <!-- 瓒嬪娍鍥惧崱鐗?-->     <div class="chart-row">       <ContentWrap class="chart-card chart-card--main">         <div class="chart-header">           <div class="chart-header__title">鎴愭湰瓒嬪娍</div>           <div class="chart-header__legend">             <span class="legend-dot" style="background: #3B82F6"></span> 鐩存帴鏉愭枡             <span class="legend-dot" style="background: #10B981"></span> 鐩存帴浜哄伐             <span class="legend-dot" style="background: #F59E0B"></span> 鍒堕€犺垂鐢?            <span class="legend-dot" style="background: #EF4444"></span> 鎬绘垚鏈?          </div>         </div>         <div class="chart-container" ref="trendChartRef"></div>       </ContentWrap>        <ContentWrap class="chart-card chart-card--side">         <div class="chart-header">           <div class="chart-header__title">鎴愭湰鏋勬垚</div>         </div>         <div class="chart-container" ref="pieChartRef"></div>         <div class="composition-legend">           <div v-for="(item, index) in avgComposition" :key="index" class="legend-item">             <div class="legend-dot" :style="{ backgroundColor: item.color }"></div>             <div class="legend-label">{{ item.label }}</div>             <div class="legend-value">{{ item.percentage }}%</div>           </div>         </div>       </ContentWrap>     </div>      <!-- 鏁版嵁琛ㄦ牸 -->     <ContentWrap class="cost-table-card">       <div class="table-header">         <div class="table-header__title">鏈堝害鎴愭湰鏄庣粏</div>         <div class="table-header__count">褰撳墠鍏?<strong>{{ trendData.length }}</strong> 鏉?/div>       </div>       <el-table :data="trendData" v-loading="loading" stripe class="cost-table">         <el-table-column label="鏈堜唤" width="100" prop="accountingMonth" />         <el-table-column label="浜у搧" min-width="150" prop="productName" />         <el-table-column label="鐩存帴鏉愭枡" min-width="120" align="right">           <template #default="{ row }">             <span class="font-mono">{{ formatMoney(row.materialCost) }}</span>           </template>         </el-table-column>         <el-table-column label="鐩存帴浜哄伐" min-width="120" align="right">           <template #default="{ row }">             <span class="font-mono">{{ formatMoney(row.laborCost) }}</span>           </template>         </el-table-column>         <el-table-column label="鍒堕€犺垂鐢? min-width="120" align="right">           <template #default="{ row }">             <span class="font-mono">{{ formatMoney(row.overheadCost) }}</span>           </template>         </el-table-column>         <el-table-column label="鎬绘垚鏈? min-width="130" align="right">           <template #default="{ row }">             <span class="font-mono font-bold text-red-600">{{ formatMoney(row.totalCost) }}</span>           </template>         </el-table-column>         <el-table-column label="鐜瘮" width="100" align="right">           <template #default="{ row }">             <span v-if="row.momChange !== null" :class="row.momChange > 0 ? 'text-red-500' : 'text-emerald-500'">               {{ row.momChange > 0 ? '+' : '' }}{{ row.momChange }}%             </span>             <span v-else class="text-slate-400">-</span>           </template>         </el-table-column>       </el-table>     </ContentWrap>   </div> </template>  <script setup lang="ts"> import { ref, reactive, computed, onMounted, nextTick, watch, onUnmounted } from 'vue' import * as echarts from 'echarts'  defineOptions({ name: 'ErpProductCostTrend' })  const loading = ref(false) const trendData = ref<any[]>([]) const productList = ref<any[]>([])  const queryParams = reactive({   productId: undefined as number | undefined,   compareProductIds: [] as number[] })  const dateRange = ref<[string, string]>([   (() => {     const d = new Date()     d.setMonth(d.getMonth() - 5)     return d.toISOString().slice(0, 7)   })(),   new Date().toISOString().slice(0, 7) ])  // Chart refs const trendChartRef = ref<HTMLElement>() const pieChartRef = ref<HTMLElement>() let trendChart: echarts.ECharts | null = null let pieChart: echarts.ECharts | null = null  // M3 淇锛氫娇鐢ㄧ粺涓€鐨?API 妯″潡 import { ProductionCostApi } from '@/api/erp/production-cost'  // 骞冲潎鎴愭湰鏋勬垚 const avgComposition = computed(() => {   if (trendData.value.length === 0) return []   const totals = trendData.value.reduce(     (acc, item) => ({       material: acc.material + Number(item.materialCost || 0),       labor: acc.labor + Number(item.laborCost || 0),       depreciation: acc.depreciation + Number(item.depreciationCost || 0),       power: acc.power + Number(item.powerCost || 0),       other: acc.other + Number(item.otherCost || 0)     }),     { material: 0, labor: 0, depreciation: 0, power: 0, other: 0 }   )   const total = totals.material + totals.labor + totals.depreciation + totals.power + totals.other   if (total === 0) return []    const colors = ['#3B82F6', '#10B981', '#F59E0B', '#06B6D4', '#14B8A6']   const items = [     { label: '鐩存帴鏉愭枡', value: totals.material, color: colors[0] },     { label: '鐩存帴浜哄伐', value: totals.labor, color: colors[1] },     { label: '鎶樻棫', value: totals.depreciation, color: colors[2] },     { label: '鐢佃垂', value: totals.power, color: colors[3] },     { label: '鍏朵粬', value: totals.other, color: colors[4] }   ]    return items.map(item => ({     ...item,     percentage: Math.round((item.value / total) * 100)   })) })  const formatMoney = (value?: number | string | null) => {   const n = Number(value || 0)   return `楼${n.toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` }  const handleQuery = () => {   loadData() }  const resetQuery = () => {   queryParams.productId = undefined   queryParams.compareProductIds = []   const d = new Date()   d.setMonth(d.getMonth() - 5)   dateRange.value = [d.toISOString().slice(0, 7), new Date().toISOString().slice(0, 7)]   loadData() }  const loadData = async () => {   if (!dateRange.value || !dateRange.value[0] || !dateRange.value[1]) return    loading.value = true   try {     const [startMonth, endMonth] = dateRange.value     const months = generateMonths(startMonth, endMonth)      // M4 淇锛氬苟琛屾煡璇㈡墍鏈夋湀浠芥暟鎹紝鏇夸唬涓茶鏌ヨ     const paramsList = months.map(month => {       const params: any = { accountingMonth: month }       if (queryParams.productId) params.productId = queryParams.productId       return params     })          const results = await Promise.all(       paramsList.map(params => ProductionCostApi.getProductSummaryV2(params))     )          // 鍚堝苟缁撴灉     const allData: any[] = []     results.forEach((data, index) => {       if (data) {         data.forEach((item: any) => {           allData.push({ ...item, accountingMonth: months[index] })         })       }     })      // 璁＄畻鐜瘮     const sortedMonths = [...months].sort()     trendData.value = allData.sort((a, b) => {       if (a.accountingMonth !== b.accountingMonth) return a.accountingMonth.localeCompare(b.accountingMonth)       return (a.productId || 0) - (b.productId || 0)     })      // 璁＄畻鐜瘮鍙樺寲     for (let i = 0; i < trendData.value.length; i++) {       const current = trendData.value[i]       const prevMonth = getPreviousMonth(current.accountingMonth)       const prev = trendData.value.find(         (item: any) => item.accountingMonth === prevMonth && item.productId === current.productId       )       if (prev && Number(prev.totalCost) > 0) {         current.momChange = Math.round(           ((Number(current.totalCost) - Number(prev.totalCost)) / Number(prev.totalCost)) * 100         )       } else {         current.momChange = null       }     }      await nextTick()     renderTrendChart()     renderPieChart()   } finally {     loading.value = false   } }  const generateMonths = (start: string, end: string): string[] => {   const months: string[] = []   let current = new Date(start + '-01')   const endDate = new Date(end + '-01')   while (current <= endDate) {     months.push(current.toISOString().slice(0, 7))     current.setMonth(current.getMonth() + 1)   }   return months }  const getPreviousMonth = (month: string): string => {   const d = new Date(month + '-01')   d.setMonth(d.getMonth() - 1)   return d.toISOString().slice(0, 7) }  const renderTrendChart = () => {   if (!trendChartRef.value) return    if (!trendChart) {     trendChart = echarts.init(trendChartRef.value)   }    const months = [...new Set(trendData.value.map((item: any) => item.accountingMonth))].sort()    // 鎸変骇鍝佸垎缁?  const productIds = queryParams.productId     ? [queryParams.productId]     : [...new Set(trendData.value.map((item: any) => item.productId))].slice(0, 5)    const series: any[] = []   const colors = ['#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#06B6D4']    productIds.forEach((productId, index) => {     const productData = trendData.value.filter((item: any) => item.productId === productId)     const productName = productData[0]?.productName || `浜у搧${productId}`      // 鏉愭枡鎴愭湰     series.push({       name: `${productName} - 鏉愭枡`,       type: 'line',       smooth: true,       symbol: 'circle',       symbolSize: 6,       lineStyle: { width: 2, color: colors[index % colors.length] },       itemStyle: { color: colors[index % colors.length] },       data: months.map(month => {         const item = productData.find((d: any) => d.accountingMonth === month)         return item ? Number(item.materialCost || 0) : null       })     })      // 鎬绘垚鏈紙铏氱嚎锛?    series.push({       name: `${productName} - 鎬绘垚鏈琡,       type: 'line',       smooth: true,       symbol: 'diamond',       symbolSize: 8,       lineStyle: { width: 2, type: 'dashed', color: colors[index % colors.length] },       itemStyle: { color: colors[index % colors.length] },       data: months.map(month => {         const item = productData.find((d: any) => d.accountingMonth === month)         return item ? Number(item.totalCost || 0) : null       })     })   })    const option = {     tooltip: {       trigger: 'axis',       formatter: (params: any) => {         if (!params || params.length === 0) return ''         let html = `<div style="font-weight:600;margin-bottom:4px">${params[0].axisValue}</div>`         params.forEach((p: any) => {           html += `<div>${p.marker} ${p.seriesName}: 楼${Number(p.value || 0).toLocaleString()}</div>`         })         return html       }     },     grid: {       left: 60,       right: 20,       top: 20,       bottom: 30     },     xAxis: {       type: 'category',       data: months,       axisLine: { lineStyle: { color: '#E2E8F0' } },       axisLabel: { color: '#64748B', fontSize: 12 }     },     yAxis: {       type: 'value',       axisLine: { show: false },       splitLine: { lineStyle: { color: '#F1F5F9' } },       axisLabel: {         color: '#64748B',         fontSize: 12,         formatter: (val: number) => `楼${(val / 1000).toFixed(0)}k`       }     },     series   }    trendChart.setOption(option, true) }  const renderPieChart = () => {   if (!pieChartRef.value || avgComposition.value.length === 0) return    if (!pieChart) {     pieChart = echarts.init(pieChartRef.value)   }    const option = {     tooltip: {       trigger: 'item',       formatter: '{b}: {c} ({d}%)'     },     series: [       {         type: 'pie',         radius: ['40%', '70%'],         center: ['50%', '50%'],         avoidLabelOverlap: false,         itemStyle: {           borderRadius: 6,           borderColor: '#fff',           borderWidth: 2         },         label: { show: false },         emphasis: {           label: { show: true, fontSize: 14, fontWeight: 'bold' }         },         data: avgComposition.value.map(item => ({           value: item.value,           name: item.label,           itemStyle: { color: item.color }         }))       }     ]   }    pieChart.setOption(option, true) }  // 鍝嶅簲寮忚皟鏁?const handleResize = () => {   trendChart?.resize()   pieChart?.resize() }  onMounted(async () => {   // 鍔犺浇鏈夋垚鏈褰曠殑浜у搧鍒楄〃   // 娉ㄦ剰锛氬繀椤荤敤 getCostProductList锛堝彧杩斿洖鏈夋垚鏈褰曠殑鎴愬搧锛夛紝绂佹鎹㈡垚 getProductSimpleList锛堜細娣峰叆鐗╂枡锛?  try {     productList.value = await ProductionCostApi.getCostProductList()   } catch {}    await loadData()   window.addEventListener('resize', handleResize) })  onUnmounted(() => {   window.removeEventListener('resize', handleResize)   trendChart?.dispose()   pieChart?.dispose() })  watch(() => dateRange.value, () => {   if (dateRange.value && dateRange.value[0] && dateRange.value[1]) {     loadData()   } }) </script>  <style scoped lang="scss"> .cost-trend-page {   display: flex;   flex-direction: column;   gap: 16px;   padding: 16px;   background: var(--erp-slate-50);   min-height: 100vh; }  .page-header-card {   .page-header {     display: flex;     justify-content: space-between;     align-items: center;     flex-wrap: wrap;     gap: 12px;   }   .page-header__title {     font-size: 20px;     font-weight: 800;     color: var(--erp-slate-900);   }   .page-header__desc {     margin-top: 4px;     color: var(--erp-slate-500);     font-size: 12px;   }   .page-header__actions {     display: flex;     gap: 12px;   } }  .filter-card {   .filter-grid {     display: grid;     grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));     gap: 16px;   }   .filter-actions {     display: flex;     justify-content: flex-end;     gap: 8px;     margin-top: 16px;   } }  .chart-row {   display: grid;   grid-template-columns: 2fr 1fr;   gap: 16px; }  .chart-card {   background: white;   border-radius: 10px;   border: 1px solid var(--erp-slate-100);   padding: 16px; }  .chart-header {   display: flex;   justify-content: space-between;   align-items: center;   margin-bottom: 12px; }  .chart-header__title {   font-size: 14px;   font-weight: 600;   color: var(--erp-slate-700); }  .chart-header__legend {   display: flex;   gap: 12px;   font-size: 12px;   color: var(--erp-slate-500); }  .legend-dot {   display: inline-block;   width: 8px;   height: 8px;   border-radius: 2px;   margin-right: 4px; }  .chart-container {   width: 100%;   height: 300px; }  .composition-legend {   margin-top: 12px;   display: flex;   flex-direction: column;   gap: 8px; }  .legend-item {   display: flex;   align-items: center;   gap: 8px;   font-size: 13px; }  .legend-label {   flex: 1;   color: var(--erp-slate-600); }  .legend-value {   font-weight: 600;   color: var(--erp-slate-900); }  .cost-table-card {   .table-header {     display: flex;     justify-content: space-between;     align-items: center;     margin-bottom: 16px;   }   .table-header__title {     font-size: 14px;     font-weight: 600;     color: var(--erp-slate-700);   }   .table-header__count {     font-size: 13px;     color: var(--erp-slate-500);   } }  .cost-table {   :deep(.el-table__header-wrapper th) {     background: var(--erp-slate-50);     color: var(--erp-slate-600);     font-weight: 600;     font-size: 12px;   } } </style>